package com.globalhire.controller;import com.globalhire.entity.Country;import com.globalhire.repository.CountryRepository;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/compliance")public class ComplianceController{final CountryRepository repo;public ComplianceController(CountryRepository r){repo=r;}@PostMapping("/analyze")public Map<String,Object> analyze(@RequestBody Map<String,Object>b){Country c=repo.findByNameIgnoreCase((String)b.get("country")).orElseThrow();double score=100-(c.isVisaRequirement()?20:0)-(c.isWorkPermit()?10:0)-(c.isSponsorship()?10:0)-(c.getEmployerTax()>25?5:0);String cat=score>=75?"LOW RISK":score>=50?"MEDIUM RISK":"HIGHER COMPLIANCE ATTENTION";return Map.of("country",c.getName(),"score",score,"category",cat,"requirements",c.getComplianceRequirements(),"disclaimer","Decision-support only; verify with qualified legal/payroll professionals.");}}